import {tasks} from './workflow.js';
export const lessons={
 sharepointCleanup:{why:'Preventing the AI from creating new links does not remove a link it already made. Inspect existing access and identify the exact link that needs cleanup.',hint:'Open Manage access for the internal guest brief. In Links, copy the broad sharing link itself, not the document address from the browser.'},
 outlookPhishing:{why:'An AI recap may misstate an approval. Check who authorized the action, who receives the information, and which files are needed before sending.',hint:'Search Outlook for the meeting-notes trial and read the recap. In Blissify, report the request and rebuild the draft for the saved venue contact with only the approved update.'},
 outlookRetry:{why:'Canceling a draft does not change the agent rule that produced it. Contain the source of the unauthorized action, then verify that normal work still runs.',hint:'Search Outlook for a VowPilot delivery failure. Open its job, cancel the queued email, and advance the simulation to see what creates a new one.'},
 phoneAudit:{why:'An assistant that only needs to draft from an approved folder should not be able to send messages or make files public. A narrow grant limits what happens if the assistant follows an unexpected instruction.',hint:'Look for the activity that gave someone access to a file. Then leave only the folder access needed to create a draft and replay.'},
 supportReported:{why:'A polished support site can be an exfiltration trap. Requests to restore AI access do not justify sending original client records to an unverified provider.',hint:'Inspect partner support, identify the unnecessary original financial records, and confirm the provider through the saved directory. Coordination records this final report after approval.'},
 messagesReported:{why:'AI can imitate a familiar voice. Judge the request, pause risky actions, and report through the normal security channel so the team can respond.',hint:'Listen for changed bank details, verification-code requests, demands for original records, or pressure to skip a procedure. Routine requests can be confirmed good.'},
 verified:{why:'A convincing voice or AI-written message does not authorize a payment change. Independent verification prevents impersonation from becoming a financial action.',hint:'Use the saved contact in your printed vendor directory, rather than the number supplied in the incoming message.'},
 safetyReady:{why:'Limit an AI assistant to the sources this task needs. Unnecessary work-data or web access can introduce private information and untrusted instructions. Source scoping does not replace redaction or injection checks.',hint:'This task needs prepared files only. Review both source switches, save the settings, and ask Finance to cross-check them.'},
 redacted:{why:'An assistant only needs relevant totals to calculate a budget. Removing identifiers and individual guest details reduces the sensitive information shared with AI.',hint:'Remove client identifiers, account and contact details, and individual health information. Keep budget and expense amounts readable; apply the redactions before sharing.'},
 guestBrief:{why:'AI can plan from anonymous requirements without receiving named guest records. Data minimization keeps useful information while reducing privacy exposure.',hint:'Find your physical guest brief card. Check the guest count and access and meal requirements, then enter the code printed on that card.'},
 financeReady:{why:'AI can sound confident while misunderstanding a financial record. Checking the original contract establishes trusted facts for the later AI calculation.',hint:'Find the access code on the physical venue contract, compare the digital copy with the paper terms, and verify the deposit and account before co-signing.'},
 guestConfirmed:{why:'An independent human check catches missing requirements before AI builds a plan from incomplete inputs.',hint:'Compare the Planning team’s brief with the source card. Verify the count, step-free access, and meal accommodations.'},
 venueConfirmed:{why:'A second source check helps prevent an impersonated message or AI recommendation from changing a trusted payee.',hint:'Compare Coordination’s callback evidence with the separate contract, including the account ending.'},
 privacyConfirmed:{why:'A document can appear redacted yet still expose unnecessary details or omit needed totals. Review the actual prepared copy before sending it to AI.',hint:'Confirm identifiers and individual guest details are absent, while the budget and relevant costs remain available.'},
 sourcesConfirmed:{why:'A second reviewer verifies that AI access matches the task. Turning sources off is one control, not a guarantee that documents contain no injection.',hint:'Check the Privacy team’s saved source settings. This calculation needs neither broad work-data grounding nor web search.'},
 attackObserved:{why:'Prompt injection happens when untrusted content is treated as authority. A supplier quote can contain normal business facts alongside instructions aimed at the AI.',hint:'Use the magnifier to inspect the whole quote, including small print. Select text that tells the assistant what to do rather than describing the catering.'},
 injection:{why:'External documents are evidence, not permission to override policy. Inspecting the quote, selecting the malicious passage, and excluding that instruction preserves useful facts without accepting the attacker’s directions.',hint:'Select the passage that redirects the assistant, then explain how it attempts to override a safety rule or change an action.'},
 paymentRejected:{why:'AI output must not authorize a new payee. Requiring human approval and trusted evidence limits the impact of an injected instruction.',hint:'Compare the proposed account with the independently verified contract. Decide whether the document author had authority to request that change.'},
 planned:{why:'AI is useful for arithmetic and drafting when its inputs are limited and reviewed. You remain responsible for checking what you send and for validating the output.',hint:'Wait for the team handoffs, attach the prepared summary, quote and anonymous requirements, then review the input before sending your planning request.'},
 reviewed:{why:'A fluent AI answer may contain incorrect calculations, missing charges, or lost accessibility requirements. Independent review checks its output against trusted sources.',hint:'Check source prices, service charge, treatment of the deposit, and both guest accommodations before confirming the plan.'},
 approved:{why:'Consequential actions need human accountability. A second reviewer provides a final check that an AI-assisted plan has not changed the vendor, payment details, or client requirements.',hint:'Use the separate Finance approval card and have another person compare the final arrangements with the verified evidence.'}
};
export function guideTask(page,state,preferred){
 const own=tasks.filter(t=>t.role===state.activeRole&&!t.hidden&&(!t.sharedOnly||state.sharedWorkshop)&&(!t.requires||state[t.requires]));
 if(preferred){const selected=tasks.find(t=>t.id===preferred&&!t.hidden&&(!t.sharedOnly||state.sharedWorkshop)&&(!t.requires||state[t.requires]));if(selected)return selected}
 const local=own.filter(t=>t.page===page);
 return local.find(t=>!state[t.id]&&t.deps.every(id=>state[id]))||local.find(t=>!state[t.id])||local[0]||own.find(t=>!state[t.id]&&t.deps.every(id=>state[id]))||own.find(t=>!state[t.id])||own[0]||null;
}
